examples.setup:
class Message(val id: String, val author: String, val text: String, val time: Long)
val now = remember { System.currentTimeMillis() }
val people = listOf("Alex Morgan", "Sam Lee", "Riley Chen")
val lines = listOf("Morning! Is the release still on for Thursday?", "Yes, the checklist is nearly done.", "I will update the notes after lunch.", "Can someone review the new onboarding copy?", "Looks good to me.", "Shipping the fix now.")
fun message(n: Int) = Message(
    id = "msg-$n",
    author = people[(n / 3) % people.size],
    text = lines[n % lines.size] + " (#" + (n + 1) + ")",
    time = now - (1500 + 500 - n) * 420_000L,
)
var messages by remember { mutableStateOf((1500 until 1500 + 500).map { message(it) }) }
var scrollTo by remember { mutableStateOf<String?>(null) }

